// 원복(해제)은 자동으로 하지 않는다. 사람이 확인한 뒤 approver(이름)와 함께 부른다. 순서: 경계(pfSense) → 앱(포털).
const b = $input.first().json.body || {};
const CFG = { dry_run: true, live_release_enabled: false };   // 실제 해제는 포털 키·pfSense 수단이 정해진 뒤 false
// 단일 PC(11/09): 포털 키·pfSense 전용 키가 갖춰져, 본문 dry_run:false(불리언)일 때만 실제 해제한다. 웹훅은 Header Auth.
if (b.dry_run === false) { CFG.dry_run = false; CFG.live_release_enabled = true; }
if (!CFG.dry_run && !CFG.live_release_enabled) return [{json:{ok:false,stop:true,no_action:true,verdict:'held_live_release_not_accepted'}}];
const need = ['seat', 'case_id', 'group_key', 'approver'];
const missing = need.filter(k => !b[k] || typeof b[k] !== 'string');
if (missing.length) return [{ json: { ok: false, verdict: 'invalid_input', missing, stop: true } }];
if (!['A', 'B', 'C', 'D'].includes(b.seat)) return [{ json: { ok: false, verdict: 'invalid_input', detail: 'seat', stop: true } }];
const X = { seat: b.seat, case_id: b.case_id, group_key: b.group_key, approver: b.approver.slice(0, 40), asset_id: b.asset_id || 'haedam-portal', cfg: CFG, reason: b.reason ? String(b.reason).slice(0, 200) : null };
return [{ json: { mode: 'check', seat: b.seat, group_key: b.group_key, ctx: X, stop: false } }];

const validText = v => typeof v === 'string' && v.length > 0 && v.length <= 300 && !/[\x00-\x1f\x7f]/.test(v);
const ticketId = v => typeof v === 'string' && /^T-\d{8}-\d{4}$/.test(v);
const states = ['open','responding','verified','restored','closed'];
const canon = a => a.via === 'pfsense' && a.action === 'fw_block' ? 'block' : a.action;
const same = (a,b) => a.bot === b.bot && a.via === b.via && canon(a) === canon(b) && a.target === b.target;
const refOK = (a, dry=false) => a && typeof a.bot === 'string' && /^(\d{3}|manual)$/.test(a.bot) && ['portal','pfsense','wazuh-ar','manual'].includes(a.via) && typeof a.action === 'string' && /^[a-z][a-z_]{1,31}$/.test(a.action) && validText(a.target) && (a.result === undefined || ['applied','already_applied'].includes(a.result) || (dry && a.result === 'dry_run'));
const held = (ctx,code) => [{json:{ok:false,no_action:true,verdict:code,ctx}}];
const snapshotOK = j => j.ok === true && typeof j.exists === 'boolean' && Array.isArray(j.actions) && j.actions.every(a=>refOK(a,!!j.ctx?.cfg?.dry_run) && (['applied','already_applied'].includes(a.result) || (j.ctx?.cfg?.dry_run && a.result==='dry_run'))) && (j.exists ? ticketId(j.ticket_id) && states.includes(j.status) : j.ticket_id === null && j.status === null && j.actions.length === 0);

const j=$input.first().json,x=j.ctx;
if (!snapshotOK(j)) return held(x,'held_ticket_check');
if (!j.exists) return [{json:{ok:true,no_action:true,verdict:'no_open_ticket'}}];
const actions=j.actions.map(a=>({...a,action:canon(a)}));
if (['restored','closed'].includes(j.status) && actions.length) return held(x,'held_inconsistent_ticket_cycle');
const selected=actions.filter(a=>a.bot==='112' && a.action==='block' && ['portal','pfsense'].includes(a.via));
const ips=[...new Set(selected.map(a=>a.target))];
if (!ips.length) return [{json:{ok:true,no_action:true,verdict:'nothing_to_release',ticket_id:j.ticket_id}}];
if (ips.length!==1) return held(x,'held_multiple_targets');
const resources=[...new Set(selected.map(a=>a.via))].sort().map(via=>({asset_id:x.asset_id,via,action:'block',target:ips[0]}));
return [{json:{ok:true,mode:'active',resource:resources[0],ctx:{...x,ticket_id:j.ticket_id,ip:ips[0],resources,resource_index:0,hasFw:selected.some(a=>a.via==='pfsense'),hasApp:selected.some(a=>a.via==='portal'),manual_required:actions.filter(a=>!selected.includes(a)).map(a=>`${a.bot}:${a.via}:${a.action}:${a.target}`)}}}];

const validText = v => typeof v === 'string' && v.length > 0 && v.length <= 300 && !/[\x00-\x1f\x7f]/.test(v);
const ticketId = v => typeof v === 'string' && /^T-\d{8}-\d{4}$/.test(v);
const states = ['open','responding','verified','restored','closed'];
const canon = a => a.via === 'pfsense' && a.action === 'fw_block' ? 'block' : a.action;
const same = (a,b) => a.bot === b.bot && a.via === b.via && canon(a) === canon(b) && a.target === b.target;
const refOK = (a, dry=false) => a && typeof a.bot === 'string' && /^(\d{3}|manual)$/.test(a.bot) && ['portal','pfsense','wazuh-ar','manual'].includes(a.via) && typeof a.action === 'string' && /^[a-z][a-z_]{1,31}$/.test(a.action) && validText(a.target) && (a.result === undefined || ['applied','already_applied'].includes(a.result) || (dry && a.result === 'dry_run'));
const held = (ctx,code) => [{json:{ok:false,no_action:true,verdict:code,ctx}}];
const snapshotOK = j => j.ok === true && typeof j.exists === 'boolean' && Array.isArray(j.actions) && j.actions.every(a=>refOK(a,!!j.ctx?.cfg?.dry_run) && (['applied','already_applied'].includes(a.result) || (j.ctx?.cfg?.dry_run && a.result==='dry_run'))) && (j.exists ? ticketId(j.ticket_id) && states.includes(j.status) : j.ticket_id === null && j.status === null && j.actions.length === 0);

const j=$input.first().json,x=j.ctx,r=x.resources[x.resource_index];
if (j.ok!==true || !j.resource || !['asset_id','via','action','target'].every(k=>j.resource[k]===r[k]) || !Array.isArray(j.tickets) || !j.tickets.every(t=>ticketId(t.ticket_id) && states.includes(t.status) && Array.isArray(t.active_actions) && t.active_actions.length>0 && t.active_actions.every(a=>refOK(a,!!x.cfg.dry_run) && a.via===r.via && canon(a)===r.action && a.target===r.target))) return held(x,'held_resource_check');
if (!j.tickets.some(t=>t.ticket_id===x.ticket_id && t.active_actions.some(a=>a.bot==='112'))) return held(x,'held_own_claim_missing');
const others=j.tickets.filter(t=>t.ticket_id!==x.ticket_id || t.active_actions.some(a=>a.bot!=='112'));
if (others.length) return [{json:{ok:true,no_action:true,verdict:'held_other_resource_ticket',other_tickets:others.map(t=>t.ticket_id),ctx:x}}];
const next=x.resource_index+1;
if (next<x.resources.length) return [{json:{ok:true,more_resources:true,mode:'active',resource:x.resources[next],ctx:{...x,resource_index:next}}}];
return [{json:{ok:true,proceed:true,more_resources:false,ctx:x}}];

if ($input.first().json.ok !== true) throw new Error('RELEASE_RECORD_REQUIRED');
const r = $input.first().json;
const x = r.ctx;
const ticket_id = x.ticket_id;
return [{ json: { ctx: x, ticket_id, dry_run: x.cfg.dry_run, action: x.abort || !x.hasFw ? 'skip' : 'unblock', ip: x.ip } }];

// 해제 결과를 티켓에 기록(stage released). 실패하면 기록하지 않고 중단 표시.
const r = $input.first().json;
const x = r.ctx;
if (r.result === 'skipped') return [{ json: { ctx: x, mode: 'record', stage: 'detected', seat: x.seat, case_id: x.case_id, group_key: x.group_key, title: x.title || x.case_id,
  asset_id: x.asset_id, event_ids: [`release-skip-${$execution.id}-1`], idempotency_key: `${$execution.id}-skip-1` } }];
// pfSense 도구의 applied_verified는 '지금 차단이 적용돼 있는가'다. 해제 성공이면 false, 아직 적용돼 있으면 true(11/09 실측).
if (r.result === 'released' && r.applied_verified === true) throw new Error('RELEASE_STATE_MISMATCH');
const ok = ['released', 'already_applied', 'dry_run'].includes(r.result);
const res = { step: 1, result: ok ? 'released' : r.result, detail: r.detail };
if (!ok) return [{ json: { ctx: { ...x, abort: true, results: [...(x.results || []), res] }, mode: 'record', stage: 'detected', seat: x.seat, case_id: x.case_id, group_key: x.group_key,
  title: x.title || x.case_id, asset_id: x.asset_id, event_ids: [`release-fail-${$execution.id}-1`], idempotency_key: `${$execution.id}-fail-1` } }];
const now = new Date().toISOString();
return [{ json: { ctx: { ...x, results: [...(x.results || []), res] }, mode: 'record', stage: 'released', seat: x.seat, case_id: x.case_id, group_key: x.group_key, title: x.title || x.case_id,
  asset_id: x.asset_id, event_ids: [`release-${$execution.id}-1`], idempotency_key: `${$execution.id}-released-1`,
  action: { bot: '112', target: x.ip, via: 'pfsense', action: 'unblock', result: 'released', applied_verified: r.applied_verified ?? null, effect_verified: null, effect_verified_at: null,
    requested_at: r.requested_at || now, finished_at: r.finished_at || now, n8n_execution_id: String($execution.id), detail: `승인 ${x.approver}${r.result === 'already_applied' ? ' (이미 해제됨)' : ''}`.slice(0, 300) } } }];

if ($input.first().json.ok !== true) throw new Error('RELEASE_RECORD_REQUIRED');
const r = $input.first().json;
const x = r.ctx;
const ticket_id = x.ticket_id;
return [{ json: { ctx: x, ticket_id, dry_run: x.cfg.dry_run, action: x.abort || !x.hasApp ? 'skip' : 'unblock', ip: x.ip } }];

// 해제 결과를 티켓에 기록(stage released). 실패하면 기록하지 않고 중단 표시.
const r = $input.first().json;
const x = r.ctx;
if (r.result === 'skipped') return [{ json: { ctx: x, mode: 'record', stage: 'detected', seat: x.seat, case_id: x.case_id, group_key: x.group_key, title: x.title || x.case_id,
  asset_id: x.asset_id, event_ids: [`release-skip-${$execution.id}-2`], idempotency_key: `${$execution.id}-skip-2` } }];
if (r.applied_verified === false) throw new Error('RELEASE_STATE_MISMATCH');
const ok = ['released', 'already_applied', 'dry_run'].includes(r.result);
const res = { step: 2, result: ok ? 'released' : r.result, detail: r.detail };
if (!ok) return [{ json: { ctx: { ...x, abort: true, results: [...(x.results || []), res] }, mode: 'record', stage: 'detected', seat: x.seat, case_id: x.case_id, group_key: x.group_key,
  title: x.title || x.case_id, asset_id: x.asset_id, event_ids: [`release-fail-${$execution.id}-2`], idempotency_key: `${$execution.id}-fail-2` } }];
const now = new Date().toISOString();
return [{ json: { ctx: { ...x, results: [...(x.results || []), res] }, mode: 'record', stage: 'released', seat: x.seat, case_id: x.case_id, group_key: x.group_key, title: x.title || x.case_id,
  asset_id: x.asset_id, event_ids: [`release-${$execution.id}-2`], idempotency_key: `${$execution.id}-released-2`,
  action: { bot: '112', target: x.ip, via: 'portal', action: 'unblock', result: 'released', applied_verified: r.applied_verified ?? null, effect_verified: null, effect_verified_at: null,
    requested_at: r.requested_at || now, finished_at: r.finished_at || now, n8n_execution_id: String($execution.id), detail: `승인 ${x.approver}${r.result === 'already_applied' ? ' (이미 해제됨)' : ''}`.slice(0, 300) } } }];

if ($input.first().json.ok !== true) throw new Error('RELEASE_RECORD_REQUIRED');
const r = $input.first().json;
const x = r.ctx;
const failed = (x.results || []).some(s => !['released'].includes(s.result));
return [{ json: { ctx: { ...x, ticket: { ticket_id: r.ticket_id, status: r.status } }, level: failed ? 'error' : 'info', case_id: x.case_id, title: failed ? '원복 중단(해제 실패)' : '원복 완료',
  src_ip: x.ip, ticket_id: r.ticket_id, result: (x.results || []).map(s => s.result).join(', '),
  detail: `승인 ${x.approver}` + (x.manual_required && x.manual_required.length ? ' / 사람이 직접 할 것: ' + x.manual_required.join(', ') : '') } }];

const r = $input.first().json;
const x = r.ctx;
return [{ json: { ok: !(x.results || []).some(s => s.result !== 'released'), verdict: x.cfg.dry_run ? 'dry_run' : 'released', case_id: x.case_id, ip: x.ip, steps: x.results, ticket: x.ticket,
  manual_required: x.manual_required, discord_sent: r.sent, n8n_execution_id: $execution.id } }];
